import {Chess} from './vendor/chess.js';
export function configureLessons(lessons,sparse){
 const position=(pieces,move,task,why)=>({fen:sparse(pieces),move,task,why,positionKind:'composed-exercise'});
 const replay=(moves,move,task,why)=>{const g=new Chess();moves.forEach(m=>g.move(m));return {fen:g.fen(),setupMoves:moves,positionKind:'replayed-game',move,task,why}};
 const transfers={
 knight:replay(['d4','d5'],'b1c3','Make one legal knight hop. Choose either White knight.','The knight jumps in an L shape even when other pieces surround it.'),
 bishop:replay(['d4','d5'],'c1f4','Move a White bishop along a clear diagonal.','Moving the d-pawn opened the c1 bishop’s diagonal.'),
 rook:position({a1:'K',h8:'k',d4:'R'},'d4d7','Move the rook along a clear rank or file.','A rook keeps either its file or its rank when it moves.'),
 queen:position({a1:'K',h7:'k',d4:'Q'},'d4f6','Make a legal queen move on a rank, file or diagonal.','The queen combines straight lines and diagonals.'),
 king:position({d3:'K',h8:'k',a2:'P'},'d3e3','Move the king one square safely.','The king can move one square, provided the destination is safe.'),
 pawn:replay(['a3','a6'],'d2d4','Advance a White pawn into an empty square.','A pawn can advance one square, or two from its starting rank if both squares are empty.'),
 'pawn-capture':replay(['d4','e5'],'d4e5','Capture Black’s pawn with a pawn.','A White pawn captures one square diagonally toward rank 8.'),
 castling:replay(['d4','d5','Nf3','Nf6','e3','e6','Bd3','Bd6'],'e1g1','Find the special move that shelters the king and activates a rook.','The safe king path is clear; castling moves both king and rook.'),
 'en-passant':replay(['d4','a6','d5','e5'],'d5e6','Use the special pawn capture available immediately after Black’s last move.','The pawn on d5 takes en passant on e6, removing the pawn on e5.'),
 promotion:position({a1:'K',h7:'k',d7:'P'},'d7d8q','Promote the pawn to a queen.','A pawn must become a new piece on the final rank.'),
 check:position({d1:'K',h8:'k',d8:'r'},'d1c1','Get your king out of the rook’s check.','Leaving the rook’s file removes the check.'),
 'back-rank':position({a1:'K',g8:'k',f7:'p',g7:'p',h7:'p',e1:'R'},'e1e8','Deliver checkmate on the back rank.','The rook checks along rank 8 while Black’s pawns block the escapes.'),
 fork:position({a1:'K',h8:'k',e7:'q',e5:'N'},'e5g6','Find a knight check that also attacks the queen.','Ng6 checks h8 and attacks e7; the queen cannot capture the knight.'),
 center:replay(['Nf3','Nf6'],'d2d4','Claim central space with a central pawn.','d4 and e4 both occupy the center and open a line for a bishop.'),
 development:replay(['d4','d5'],'g1f3','Develop a knight toward the center.','Nc3 and Nf3 develop a piece toward central squares.'),
 opposition:position({d4:'K',d7:'k',d3:'P'},'d4d5','Take the direct opposition against Black’s king.','After Kd5, one square separates the kings and Black must give way.'),
 'rook-activity':position({a1:'K',g8:'k',a4:'R',d5:'P'},'a4d4','Place the rook behind your passed pawn.','The rook supports the d-pawn from behind along the d-file.'),
 'queen-mate':position({f6:'K',h8:'k',f7:'Q'},'f7g7','Deliver checkmate with your queen and king.','The king protects g7, and the queen covers every escape.'),
 };
 for(const l of lessons){
  l.stopAfterGoal=true;l.transfer=transfers[l.id];
  l.selection=l.phase==='Foundations'?'focus':'any';
  l.goal=['knight','bishop','rook','queen','king','pawn'].includes(l.id)?'movement':l.id==='check'?'escape':l.mate?'mate':'target';
  l.chapter=l.phase==='Foundations'?'01 · Pieces & rules':l.phase==='Openings'?'02 · Opening plans':l.phase==='Middlegame'?'03 · Tactical patterns':'04 · Endgame tools';
 }
 const knight=lessons.find(l=>l.id==='knight');
 delete knight.practiceGoal;delete knight.demoMoves;
 Object.assign(knight,{cue:'Watch the L shape: two squares along a rank or file, then one sideways. Knights can jump over other pieces.',task:'Make one legal move with either White knight.',why:'Your knight made a legal L-shaped hop over the starting pawns. That is the whole goal — the board stops here.'});
 const generalWhy={bishop:'The bishop stayed on a clear diagonal. It cannot jump, and it always remains on the same square color.',rook:'The rook followed a clear rank or file without jumping over a piece.',queen:'The queen moved along a clear rank, file or diagonal without jumping.',king:'Your king moved one square to a safe destination.',pawn:'The pawn advanced into an empty square. A two-square move is available only from its starting rank when both squares are clear.',center:'The central pawn claims space and opens a line for a bishop. Both e4 and d4 are sound ways to begin.',development:'The knight joins the game on a central-facing square. Nc3 controls d5 and e4; Nf3 controls d4 and e5.'};
 for(const l of lessons)if(generalWhy[l.id])l.why=generalWhy[l.id];
 const center=lessons.find(l=>l.id==='center');center.answers=['e2e4','d2d4'];center.task='Claim the center with e4 or d4.';
 const development=lessons.find(l=>l.id==='development');development.answers=['g1f3','b1c3'];development.task='Develop either knight toward the center: Nf3 or Nc3.';development.why=generalWhy.development;center.why=generalWhy.center;
 const additions=[
 {id:'loose-piece',name:'Notice the free piece',focus:'r',intro:'Before calculating a combination, check whether an enemy piece is undefended.',cue:'Look along the rook’s file. Can it take the queen safely?',mistake:'An attacked piece is not always free. Check whether the capturing piece can be taken back.',task:'Capture the undefended queen.',why:'Your rook captures the queen, and the distant black king cannot recapture.',fen:sparse({a1:'K',h8:'k',d1:'R',d5:'q'}),move:'d1d5',transfer:position({a1:'K',h8:'k',e1:'R',e6:'q'},'e1e6','Capture the undefended queen.','The rook wins the queen along a clear file.')},
 {id:'absolute-pin',name:'Keep the defender pinned',focus:'b',intro:'A piece pinned to its king cannot move if doing so would expose check.',cue:'Line up your bishop, Black’s knight and Black’s king.',mistake:'A pin is not automatically a won piece. The opponent may defend the pinned piece or move the king.',task:'Move Bf1 to b5 to pin the knight to the king.',why:'The bishop on b5 attacks c6. If that knight leaves the diagonal, its king on e8 would be in check.',fen:sparse({a1:'K',e8:'k',c6:'n',f1:'B',a7:'p'}),move:'f1b5',transfer:position({a1:'K',g8:'k',g6:'n',a4:'R'},'a4g4','Use your rook to pin the knight to its king.','The rook on g4 lines up the knight on g6 with the king on g8.')},
 {id:'skewer',name:'The valuable piece in front',focus:'r',intro:'A skewer attacks a valuable front piece and exposes the piece behind it when it moves.',cue:'Check along the back rank with Black’s queen behind the king.',mistake:'Check the complete line: the back piece must really be exposed after the front piece moves.',task:'Move Ra1 to a8 to skewer the king and queen.',why:'The rook checks the king on g8 along rank 8. When the king leaves, the queen on h8 is exposed.',fen:sparse({b1:'K',g8:'k',h8:'q',a1:'R'}),move:'a1a8',transfer:position({a1:'K',e6:'k',g8:'q',e2:'B'},'e2c4','Give a bishop check that lines up the king and queen.','Bc4 checks along c4–d5–e6–f7–g8. The queen is behind the king.')},
 {id:'discovered-check',name:'Open a line with check',focus:'b',intro:'Moving one piece can uncover an attack from a piece behind it.',cue:'Your bishop is blocking your rook’s file toward the black king.',mistake:'The piece that moves must still land legally. The uncovered line must be clear all the way to the king.',task:'Move Be2 to f3 to uncover the rook’s check.',why:'The bishop leaves the e-file and the rook on e1 now checks the king on e8.',fen:sparse({a1:'K',e8:'k',e1:'R',e2:'B'}),move:'e2f3',transfer:position({a1:'K',d8:'k',d1:'R',d3:'B'},'d3e4','Uncover a rook check by moving your bishop off the file.','Be4 clears the d-file, so the rook on d1 checks the king on d8.')}
 ];
 for(const l of additions)lessons.push({...l,phase:'Middlegame',chapter:'03 · Tactical patterns',time:4,selection:'any',goal:'target',stopAfterGoal:true,positionKind:'composed-exercise'});
 lessons.find(l=>l.id==='discovered-check').goal='discovered-check';

 const expanded=[
 {id:'bishop-development',name:'Bring the bishop into play',phase:'Openings',focus:'b',intro:'After a central pawn moves, develop a bishop instead of spending another turn on the same knight.',cue:'Find the open diagonal from the bishop’s starting square.',mistake:'Check that every square on the diagonal is clear.',...replay(['e4','e5','Nf3','Nc6'],'f1c4','Develop Bf1 to c4, looking toward f7.','Bc4 develops a new piece and aims at f7. It does not win that pawn immediately.'),transfer:replay(['d4','d5','Nf3','Nf6'],'c1f4','Develop Bc1 to f4 along the open diagonal.','Bf4 brings the bishop out and influences e5.')},
 {id:'castle-preparation',name:'Clear the way to castle',phase:'Openings',focus:'b',intro:'Castling needs a clear, safe path. Developing the bishop can clear the last occupied square.',cue:'The king’s knight is developed. Now move the bishop off f1.',mistake:'Clearing the path is only one condition: the king cannot castle from, through or into check.',...replay(['e4','e5','Nf3','Nc6'],'f1e2','Move Bf1 to e2 to clear the kingside castling path.','Both f1 and g1 are now empty. White has kept the right to castle; Black moves next.'),transfer:replay(['d4','d5','Nf3','Nf6','e3','e6'],'f1d3','Move Bf1 to d3 to clear the kingside castling path.','Bd3 develops a piece and clears f1. Always check the opponent’s reply before castling.')},
 {id:'capture-checker',name:'Capture the checking piece',phase:'Foundations',focus:'k',intro:'You can answer check by capturing the attacker, if the capture leaves your king safe.',cue:'The checking rook is beside your king and has no defender.',mistake:'A king may never capture a protected piece.',...position({e1:'K',h8:'k',e2:'r',a2:'P'},'e1e2','Capture the undefended checking rook with your king.','Kxe2 removes the rook. Black’s king is too far away to attack e2.'),transfer:position({d1:'K',h8:'k',d2:'r',a2:'P'},'d1d2','Capture the checking rook on d2.','Kxd2 removes the attack and lands on a safe square.')},
 {id:'block-check',name:'Step into the line',phase:'Foundations',focus:'b',intro:'A bishop, rook or queen check can sometimes be stopped by putting a piece between the attacker and king.',cue:'Find where your bishop can cross the checking rook’s file.',mistake:'You cannot block a knight check or a check from an adjacent piece.',...position({e1:'K',h8:'k',e8:'r',d2:'B'},'d2e3','Block the rook’s check with Be3.','The bishop on e3 interrupts the e8–e1 line, so the king is no longer in check.'),transfer:position({d1:'K',h8:'k',d8:'r',c2:'B'},'c2d3','Block the rook’s check with Bd3.','Bd3 places the bishop between the rook and king.')},
 {id:'remove-attacker',name:'Take the attacker safely',phase:'Middlegame',focus:'r',intro:'Before retreating from an attack, see whether another piece can safely capture the attacker.',cue:'Black’s bishop attacks your knight. Your rook has a clear line to that bishop.',mistake:'Check whether the attacker is defended before making the capture.',...position({a1:'K',h8:'k',d1:'R',d5:'b',f3:'N'},'d1d5','Capture the bishop attacking your knight on f3.','Rxd5 removes the bishop that attacked f3. The distant king cannot recapture.'),transfer:position({a1:'K',h8:'k',e1:'R',e6:'b',g4:'N'},'e1e6','Capture the bishop attacking your knight on g4.','Rxe6 removes the bishop and preserves the knight.')},
 {id:'king-activity',name:'Bring your king closer',phase:'Endgame',focus:'k',intro:'With few pieces left, the king can help its pawns. Choose a safe square closer to the action.',cue:'Step toward your pawn without entering the enemy king’s reach.',mistake:'King activity is useful, but it does not mean walking into check.',...position({c2:'K',h8:'k',d4:'P'},'c2d3','Move Kc2 to d3 to protect the pawn on d4.','Kd3 brings the king beside its pawn and directly protects d4.'),transfer:position({f2:'K',a8:'k',e4:'P'},'f2e3','Move Kf2 to e3 to protect the pawn on e4.','Ke3 moves toward the center and directly protects e4.')},
 {id:'seventh-rank',name:'Invade the seventh rank',phase:'Endgame',focus:'r',intro:'An active rook on the seventh rank can attack pawns from the side.',cue:'Use the open file to reach a rank containing enemy pawns.',mistake:'A rook invasion needs a safe entry square; check for enemy captures.',...position({a1:'K',h8:'k',d1:'R',a7:'p',b7:'p'},'d1d7','Move Rd1 to d7 to attack the pawns along rank 7.','Rd7 attacks b7 along the rank. Black must decide how to respond.'),transfer:position({a1:'K',h8:'k',e1:'R',b7:'p',c7:'p'},'e1e7','Move Re1 to e7 to attack the seventh-rank pawns.','Re7 activates the rook and attacks c7 from the side.')},
 {id:'knight-promotion',name:'Promote with a knight check',phase:'Endgame',focus:'p',intro:'Promotion offers four choices. A knight can give a check that a queen on the same square cannot.',cue:'Imagine a knight on the promotion square and trace its L-shaped attacks.',mistake:'This exercise asks for a knight check; it does not claim that a queen loses.',...position({a1:'K',f7:'k',d7:'P'},'d7d8n','Promote d7 to a knight on d8, giving check.','A knight on d8 attacks f7. A queen on d8 would not check that king.'),transfer:position({a1:'K',c7:'k',e7:'P'},'e7e8n','Promote e7 to a knight on e8, giving check.','A knight on e8 attacks c7. Choose the piece for the position, not just its value.')}
 ];
 for(const l of expanded)lessons.push({...l,time:4,chapter:l.phase==='Foundations'?'01 · Pieces & rules':l.phase==='Openings'?'02 · Opening plans':l.phase==='Middlegame'?'03 · Tactical patterns':'04 · Endgame tools',selection:'any',goal:'target',stopAfterGoal:true});

 // Order concepts before testing them, with one recommended next lesson.
 const order=['knight','bishop','rook','queen','king','pawn','pawn-capture','check','capture-checker','block-check','castling','en-passant','center','development','bishop-development','castle-preparation','fork','loose-piece','absolute-pin','skewer','discovered-check','remove-attacker','back-rank','promotion','knight-promotion','king-activity','opposition','rook-activity','seventh-rank','queen-mate'];
 lessons.sort((a,b)=>order.indexOf(a.id)-order.indexOf(b.id));
}
